// Snap an arbitrary #rrggbb to the nearest baked preset (RGB distance).
export function nearestClassPreset(hex: string): string {
  const v = (h: string, i: number) => parseInt(h.slice(i, i + 2), 16);
  const h = hex.replace('#', '').toUpperCase().padEnd(6, '0');
  let best: string = CLASS_PRESET_HEXES[0], bestD = Infinity;
  for (const p of CLASS_PRESET_HEXES) {
    const d = (v(h,0)-v(p,1))**2 + (v(h,2)-v(p,3))**2 + (v(h,4)-v(p,5))**2;
    if (d < bestD) { bestD = d; best = p; }
  }
  return best.slice(1);
}
